-- New CBT subject: GST212 (Nigerian Peoples and Culture), University of
-- Nigeria, Nsukka, 200 Level second semester, 2 units, General Studies
-- (is_general=true, so every faculty sees it regardless of the faculty tag).
--
-- 222 questions mined from a real textbook the user supplied
-- ("Nigerian Peoples and Cultures: With Selected Topics on Responsible
-- Citizenship and Development", scanned as 99 photographed pages, not in
-- book order). Extracted via 3 parallel passes covering pages 1-33, 34-66,
-- 67-99. QA: zero structural errors (4 options, valid correct_index, no
-- duplicate options), zero exact-duplicate questions, zero meta-references
-- to "the book/text/chapter/passage" (22 caught on first pass and manually
-- rewritten to be self-contained, one broader pass fixed the last), zero
-- middle-dot rendering-crash characters. This is a new subject, GST212 had
-- no CBT bank before this.

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
values
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'How did Warfihaugh (1972) define language?', '["A system of arbitrary vocal symbols by which a social group cooperates", "A purely written form of human expression", "A biological instinct present in all animals", "A set of grammatical rules invented by scholars"]'::jsonb, 0, 'Warfihaugh (1972) defined language as a system of arbitrary vocal symbols by means of which a social group cooperates, a definition emphasizing language as a tool for human communication and cooperation.', 'Introduction to Peoples of Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Approximately how many ethnic groups does Nigeria comprise?', '["150", "250", "371", "500"]'::jsonb, 1, 'Nigeria is home to an estimated 250 ethnic groups, making it one of the most ethnically diverse countries in the world.', 'Ethnic Diversity of Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which three ethnic groups are identified as the largest in Nigeria by population?', '["Hausa, Yoruba, and Igbo", "Fulani, Kanuri, and Tiv", "Ijaw, Edo, and Nupe", "Efik, Ibibio, and Igala"]'::jsonb, 0, 'The Hausa, Yoruba, and Igbo are the largest ethnic groups in Nigeria, together comprising the majority of the population, though the country also has multiple smaller ethnic nationalities such as the Fulani, Kanuri, and Tiv.', 'Ethnic Diversity of Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Roughly how many indigenous languages have been identified as being spoken in Nigeria?', '["Fewer than 50", "About 100", "Over 500", "Exactly 250"]'::jsonb, 2, 'Nigeria has over 500 languages spoken among its native speakers, reflecting its immense linguistic diversity, with Hausa, Yoruba, Igbo, Fulfulde, and Tiv among the most popular.', 'Languages of Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Who is credited with the widely cited definition of culture as ''that complex whole which includes knowledge, belief, art, morals, law, custom...''?', '["E.B. Tylor", "Ferdinand de Saussure", "Emile Durkheim", "Bronislaw Malinowski"]'::jsonb, 0, 'Tylor''s definition of culture as a complex whole encompassing knowledge, belief, art, morals, law, and custom is one of the most frequently cited anthropological definitions of culture.', 'Definitions of Culture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Enebe (2008) added that culture is ''the knowledge, beliefs, customs, values, and skills'' available to a society by which criterion?', '["Society members through royal decree", "Which society can be compared to another", "Formal educational certification only", "International legal recognition"]'::jsonb, 1, 'Enebe (2008) held that culture is the knowledge, beliefs, customs, values, and skills available to a society, by which the society can be compared to others.', 'Definitions of Culture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What was Nigeria formerly known as before independence, according to the region''s colonial designation?', '["The Royal Niger Territories", "The Gold Coast", "British East Africa", "The Slave Coast"]'::jsonb, 0, 'The territory ''Nigeria'' was formerly known as the Royal Niger Territories, taken from the Niger river running through the country, before it was rebranded and colonized under the British.', 'Historical Background of Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In what year did Nigeria gain independence from British colonial rule?', '["1957", "1960", "1963", "1966"]'::jsonb, 1, 'Nigeria finally gained independence on October 1, 1960, after years of nationalist campaigns advocating for independence, led by figures such as Nnamdi Azikiwe.', 'Nigeria''s Independence', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Who became Nigeria''s first president after independence?', '["Nnamdi Azikiwe", "Obafemi Awolowo", "Ahmadu Bello", "Tafawa Balewa"]'::jsonb, 0, 'Nnamdi Azikiwe became Nigeria''s first president, having been one of the leading nationalist figures advocating for independence from British rule.', 'Nigeria''s Independence', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Historical evidence suggests Nok civilization complexities existed in Nigeria between which dates?', '["1000 BCE and 300 CE", "500 CE and 1000 CE", "1200 CE and 1500 CE", "50 BCE and 50 CE"]'::jsonb, 0, 'Evidence suggests that the earliest complex civilizations in Nigeria, such as the Nok civilization, flourished between 1000 BCE and 300 CE, well predating colonial contact.', 'Historical Background of Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Yoruba consider which city to be their ancestral home and the seat of the deity Oduduwa?', '["Ile-Ife", "Ibadan", "Oyo", "Ogbomosho"]'::jsonb, 0, 'The Yoruba consider the city of Ile-Ife to be their ancestral home and the seat of the deity Oduduwa, and each Yoruba subgroup is ruled by a paramount chief or Oba.', 'Yoruba Origins and Political Structure', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What title is given to the traditional spiritual leader of the Yoruba based in Ile-Ife?', '["The Ooni of Ife", "The Emir", "The Obi", "The Sultan"]'::jsonb, 0, 'The Ooni of Ife is the spiritual leader of the Yoruba and one of the most powerful traditional rulers among the Yoruba people.', 'Yoruba Origins and Political Structure', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which three ethnic groups collectively represent the majority of Nigeria''s population?', '["Hausa-Fulani, Yoruba, and Igbo", "Tiv, Nupe, and Igala", "Ijaw, Kanuri, and Efik", "Edo, Urhobo, and Itsekiri"]'::jsonb, 0, 'The Hausa-Fulani, Yoruba, and Igbo are described as the three largest ethnic groups, collectively representing the majority of Nigeria''s population.', 'Major Ethnic Groups of Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Into how many broad linguistic groups are the languages of Nigeria classified?', '["Two", "Three", "Four", "Five"]'::jsonb, 1, 'The languages of Nigeria are classified into three broad linguistic groups: Niger-Congo, Nilo-Saharan, and Afro-Asiatic.', 'Language Classification in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which language family does Yoruba, Igbo, and Efik belong to according to their linguistic classification?', '["Niger-Congo", "Nilo-Saharan", "Afro-Asiatic", "Indo-European"]'::jsonb, 0, 'Yoruba, Igbo, and Efik belong to the Niger-Congo language family, the largest of the three broad linguistic groups spoken in Nigeria.', 'Language Classification in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which subgroup of the Niger-Congo family does Hausa''s neighboring language group, Tiv and Jukun, fall under?', '["Atlantic subgroup", "Cross River subgroup", "Benue-Congo subgroup", "Mande subgroup"]'::jsonb, 2, 'Tiv and Jukun, alongside Igbo, Igala, Idoma, Nupe, and others, belong to the Benue-Congo subgroup, the most extensive subgroup within Niger-Congo.', 'Language Classification in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Hausa belongs to which of Nigeria''s three broad linguistic groups?', '["Niger-Congo", "Nilo-Saharan", "Afro-Asiatic", "Bantu"]'::jsonb, 2, 'Hausa is represented in the Afro-Asiatic group, alongside languages such as Bade, Ngizim, and Margi.', 'Language Classification in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The history of Nok art can be traced to the discovery of Nok terracotta figurines, first dated to which century?', '["9th century CE", "12th century CE", "16th century CE", "19th century CE"]'::jsonb, 0, 'Nok terracotta bronzes were first discovered in the 1930s at Nok and Jemaa, and dating placed such art as far back as the 9th century CE, revealing that highly organized artistic culture existed in Nigeria long before colonial contact.', 'Nok Art and Culture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'At the beginning of the 20th century, which religion did most Nigerians practice, despite British colonial policies discouraging it?', '["Traditional African religion", "Christianity", "Islam", "Buddhism"]'::jsonb, 0, 'At the beginning of the 20th century, most Nigerians were followers of traditional religion, despite British colonial policies that discouraged this practice to such an extent that by the beginning of the 21st century, about half of the population were classified as Muslims or Christians.', 'Religions of Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Where were Igbo Ukwu bronzes, dated to around the 9th century CE, discovered?', '["Igbo Ukwu, in eastern Nigeria", "Ile-Ife, in western Nigeria", "Benin City", "Kano"]'::jsonb, 0, 'Igbo Ukwu bronzes were discovered in the 1930s and 1940s at Igbo Ukwu, and are dated to about the 9th century CE, revealing highly sophisticated bronze-casting traditions.', 'Nok Art and Culture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'How did Anakor (2002) define art?', '["An aesthetic object which elicits an emotional and perhaps intellectual response from the beholder", "A tool used exclusively for religious worship", "A purely commercial product for trade", "A written record of oral history"]'::jsonb, 0, 'Anakor (2002) defined art as any aesthetic object which is man-made and elicits an emotional and perhaps intellectual response from the beholder, such as sculptures, paintings, or a mask head.', 'Nigerian Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which Nigerian artist became known for painting and producing sculptures displayed at Queen Elizabeth II''s 1956 visit to Nigeria?', '["Ben Enwonwu", "Bruce Onobrakpeya", "Yusuf Grillo", "Uche Okeke"]'::jsonb, 0, 'Ben Enwonwu, who painted and produced sculptures, made a bronze statue of her, and was one of the earliest of these contemporary artists displayed at Queen Elizabeth II''s 1956 visit to Nigeria.', 'Nigerian Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which category of contemporary Nigerian musician is Chief Stephen Osita Osadebe associated with?', '["Highlife music", "Afrobeats", "Fuji music", "Juju music"]'::jsonb, 0, 'Chief Stephen Osadebe is noted as an old maestro who achieved worldwide fame and had several albums that fall into the highlife category, alongside contemporaries like Oliver De Coque.', 'Contemporary Nigerian Music', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Traditional music instruments played in rural areas of Nigeria include which of the following?', '["Bows, xylophones, and wooden clappers", "Electric guitars only", "Pianos and violins", "Saxophones and trumpets"]'::jsonb, 0, 'Various traditional Nigerian musical instruments, including bows, xylophones, and wooden clappers, are played in rural areas and used at festivals, storytelling, and urban music performed at palaces.', 'Nigerian Traditional Music', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In pre-colonial Nigerian society, what served as the smallest social unit and building block of the larger social structure?', '["The extended family", "The nuclear family", "The village council", "The age-grade association"]'::jsonb, 1, 'The nuclear family, consisting of a man, his wife or wives, and children, served as the smallest social unit, with extended families being the fundamental social organizing blocks built from linkage connections among nuclear families.', 'Pre-Colonial Family Structure', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Among the Hausa, what were slaves who occupied the highest position, often referred to as royal or administrative slaves, known as?', '["Sarki or Wazirin", "Bayi", "Ghwarri or Yanwuwa", "Talakawa"]'::jsonb, 0, 'Within Hausa society, a hierarchical system called ''tsuntsu'' recognized slaves according to various social classes, with the ruling elites referred to as ''Sarki'' occupying the highest position, followed by ''Bayi'' as the lowest class.', 'Pre-Colonial Hausa Social Hierarchy', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In pre-colonial Yoruba and Igbo societies, despite patriarchal characteristics, what active role did women play?', '["They played active roles in supporting and undermining the boundaries that delineated their positions", "They held no roles outside the home", "They were completely excluded from all economic activity", "They served only as ceremonial figureheads with no real influence"]'::jsonb, 0, 'Despite patriarchal characteristics, women in Yoruba and Igbo societies played active roles in supporting and undermining the boundaries that delineated their positions in pre-colonial Nigerian society.', 'Gender Roles in Pre-Colonial Society', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Among the Igbo, what were female leaders known as ''Umu ada'' and ''Nne ada'' significant for?', '["They held influential titles wielded to promote peaceful coexistence and mark social status", "They served exclusively as market traders", "They were restricted from any leadership role", "They were only recognized in Islamic contexts"]'::jsonb, 0, 'Igbo and Yoruba women, known variously as ''Umu ada'' and ''Iyalode'', could become family heads due to their seniority, a remarkable marker of social status and influence within pre-colonial society.', 'Gender Roles in Pre-Colonial Society', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In Yoruba traditional religion, which deity is regarded as the author of light and knowledge, and fertility?', '["Chukwu", "Obatala", "Sango", "Ogun"]'::jsonb, 1, 'Obatala is regarded as the author of light and knowledge, fertility, and an embodiment of goodness, which he showers on creatures within the Yoruba pantheon of deities.', 'Yoruba Traditional Religion', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which Yoruba deity is known as the god of thunder and lightning?', '["Sango", "Esu", "Ifa", "Orunmila"]'::jsonb, 0, 'Sango, also known as Sangos wife, is the god of lightning; these orishas, including Ogun (god of iron) and Oya (goddess of wind), are venerated within the Yoruba pantheon.', 'Yoruba Traditional Religion', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Among the Hausa, solitary religion practiced with sacrifices and rituals, particularly those involving food, is known as what?', '["Bori", "Sango cult", "Ifa divination", "Odinani"]'::jsonb, 0, 'The Hausa traditional religion, known as Bori, involved conducting various rituals and sacrifices, particularly those invoking spirits for protection, and included the veneration of solitary deities.', 'Hausa Traditional Religion', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In pre-colonial Yoruba political systems, the political head of an Oyo town was known by what title?', '["Oba", "Emir", "Eze", "Obi"]'::jsonb, 0, 'In pre-colonial Yoruba political systems, an Oba was the political head of a town, referred to as an ''Oba'' or ''ang as an'' depending on regional variation, with the Yoruba being organized into numerous city-states, each with its own Oba.', 'Yoruba Pre-Colonial Political Systems', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Following the Sokoto Caliphate''s rise, political power in Hausa land was organized under a ruler known as?', '["Emir", "Oba", "Igwe", "Attah"]'::jsonb, 0, 'Under the Sokoto Caliphate, the Emir was the political head appointed by the Caliph, ruling with the assistance of officials such as the Waziri (prime minister) and the Magaji (treasurer).', 'Sokoto Caliphate Political Structure', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Igbo pre-colonial political system was described as what type of structure, in contrast to the more centralized Hausa and Yoruba systems?', '["A decentralized political structure without a single ruler", "A rigid hereditary monarchy", "A single centralized empire under one Oba", "A theocracy ruled entirely by priests"]'::jsonb, 0, 'The Igbo community maintained a decentralized political structure, dispersed rather than concentrated within a single family or group, with village elders and age-grade associations handling governance rather than a single monarch.', 'Igbo Pre-Colonial Political Structure', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Among the Igbo, what parallel organization did married women form to challenge or engage men in acts of injustice against women?', '["Umuada and Ndi iyom associations", "The Nigerian Youth Movement", "The Egbe Omo Oduduwa", "The Aba Women''s Union alone"]'::jsonb, 0, 'Igbo women formed parallel organizations, known as Umuada (unmarried women) and Ndi iyom (married women), through which they transgressed the institution of marriage or engaged/challenged men who engaged in acts of domestic violence or child abuse.', 'Igbo Women''s Organizations', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Radiocarbon dating of iron smelting evidence at Lejja in pre-colonial Igbo-Ukwu areas suggests iron working dates back to approximately what era?', '["2000 BC", "500 AD", "1500 AD", "1800 AD"]'::jsonb, 0, 'Radiocarbon dating at Lejja, which had enormous historical evidence, revealed the extraordinary antiquity of iron smelting in Igbo areas, dated to around 2000 BC.', 'Pre-Colonial Iron Working', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In pre-colonial Nigeria, what material did the Igbo mainly use for weaving baskets and mats, distinct from the Hausa who used dried elephant grass?', '["Raffia palm fronds", "Cotton fiber", "Wool", "Synthetic fiber"]'::jsonb, 0, 'Many types of natural fibres were used to weave a basket or mat; raffia from palm fronds was used mainly by the Igbo, while dry elephant grass was the commonly used material for weaving among the Hausa.', 'Pre-Colonial Craftsmanship', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which ethnic group is notably known for a huge role in the Trans-Atlantic slave trade as middlemen for coastal European traders?', '["The Aro people of Igbo ethnicity", "The Fulani of the North", "The Efik of Calabar alone", "The Nupe of the Middle Belt"]'::jsonb, 0, 'The Aro people of Igbo ethnicity are notably known for their huge role in the Transatlantic slave trade, serving as middlemen between local communities and European trading firms.', 'Pre-Colonial Trade', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What was the most generally accepted currency used in pre-colonial Nigeria''s exchange system, before the widespread use of foreign coins?', '["The cowry", "Gold dust", "Manila bars only", "Paper notes"]'::jsonb, 0, 'The cowry was the most generally accepted currency in pre-colonial Nigeria, while other commodity currencies included brass rods, manila, copper wires, iron rods, cloth, and salt.', 'Pre-Colonial Trade and Currency', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In pre-colonial Igbo markets, market days were held at regular intervals named after which cycle?', '["Eke, Afor, Orie, and Nkwo", "Monday through Friday", "A ten-day week", "Lunar phases only"]'::jsonb, 0, 'Igbo market days were held every four days, namely Eke, Afor, Orie, and Nkwo, forming central hubs of local exchange for foodstuffs and household materials such as pottery and baskets.', 'Pre-Colonial Trade', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Who coined the name ''Nigeria'' in an article published in The Times of London in 1897?', '["Flora Shaw", "Frederick Lugard", "Winston Churchill", "Mary Kingsley"]'::jsonb, 0, 'The name Nigeria was coined by Flora Shaw (later Lady Lugard) in an article published in The Times of London in 1897, before the territory was formally amalgamated in 1914.', 'Origin of the Name Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Berlin Conference, which set the rules for European colonization of Africa, was held under the leadership of which figure?', '["German Chancellor Otto von Bismarck", "British Prime Minister William Gladstone", "French President Jules Grevy", "King Leopold II of Belgium"]'::jsonb, 0, 'The Berlin Conference, held between November 1884 and February 1885, was convened under the leadership of German Chancellor Otto von Bismarck to regulate European competition in Africa.', 'The Berlin Conference', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What principle did the Berlin Conference establish that mandated European powers demonstrate actual administrative control to claim African territory?', '["The principle of ''effective occupation''", "The principle of ''first discovery''", "The principle of ''popular consent''", "The principle of ''religious conversion''"]'::jsonb, 0, 'The Berlin Conference established the principle of ''effective occupation,'' which mandated any European power claiming African territory to demonstrate actual administrative control and occupation of the area.', 'The Berlin Conference', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Approximately how many Africans were forcibly transported to the Americas as part of the transatlantic slave trade between the sixteenth and nineteenth centuries?', '["About twelve million", "About one million", "About fifty million", "About five hundred thousand"]'::jsonb, 0, 'Between the sixteenth and nineteenth centuries, almost twelve million Africans were forcibly transported to the Americas as part of the transatlantic slave trade, primarily by Portuguese, British, French, and Dutch traders.', 'The Trans-Atlantic Slave Trade', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which medical breakthrough involving the extraction of quinine helped Europeans survive tropical diseases and enabled deeper colonization of Africa''s interior?', '["Extraction of quinine from the cinchona tree bark by Pelletier and Caventou in 1817", "The discovery of penicillin", "The invention of the smallpox vaccine", "The development of anesthesia"]'::jsonb, 0, 'The extraction of quinine from the bark of the cinchona tree by Pierre-Joseph Pelletier and Joseph Bienaime Caventou in 1817 provided an effective treatment for malaria, enabling Europeans to survive and operate more effectively in Africa''s interior regions.', 'Factors Facilitating European Conquest', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In 1900, the British government took direct control of territories previously administered by which company?', '["The Royal Niger Company", "The East India Company", "The British South Africa Company", "The Hudson''s Bay Company"]'::jsonb, 0, 'In 1900, the British government took direct control of the territories previously administered by the Royal Niger Company, dividing them into the Colony of Lagos, the Protectorate of Southern Nigeria, and the Protectorate of Northern Nigeria.', 'The Amalgamation of the Protectorates', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Sir Frederick Lugard is best known for introducing which system of colonial governance that incorporated local chiefs and emirs into the administrative structure?', '["Indirect rule", "Direct rule", "Federalism", "Dual mandate trusteeship"]'::jsonb, 0, 'Lugard is best known for introducing the policy of indirect rule, a system through which traditional rulers were incorporated into the colonial administrative structure while carrying out colonial policies.', 'Lugard and Indirect Rule', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'On what date did the amalgamation of the Northern and Southern Protectorates formally take effect, creating modern Nigeria as a single political entity?', '["1 January 1914", "1 October 1960", "1 January 1900", "6 March 1945"]'::jsonb, 0, 'The formal amalgamation of the Northern and Southern Protectorates took effect on 1 January 1914, creating a single political entity known as Nigeria under Governor-General Sir Frederick Lugard.', 'The Amalgamation of the Protectorates', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Nigerian Council established under Lugard''s administration consisted of how many official and unofficial members in total?', '["Thirty-six", "Twenty", "Fifty", "Twelve"]'::jsonb, 0, 'According to Tamuno (1967), the Nigerian Council consisted of twenty-four official members and twelve unofficial members, though it possessed neither legislative authority nor financial control and functioned mainly as a consultative forum.', 'Colonial Administration of Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Sir Hugh Clifford, who succeeded Lugard as Governor in 1919, is known for introducing which major constitutional reform in 1922?', '["The Clifford Constitution, establishing a new Legislative Council with expanded powers", "The Richards Constitution", "The Macpherson Constitution", "The Independence Constitution"]'::jsonb, 0, 'One of Clifford''s major achievements was the introduction of the Clifford Constitution of 1922, which established a new Legislative Council with expanded powers and jurisdiction over most of Southern Nigeria, and introduced the elective principle into Nigerian politics for the first time.', 'The Clifford Constitution of 1922', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Nigerian National Democratic Party (NNDP), the first major political party in Nigeria, was founded in 1923 by whom?', '["Herbert Macaulay", "Nnamdi Azikiwe", "Obafemi Awolowo", "Ahmadu Bello"]'::jsonb, 0, 'The introduction of the elective principle encouraged the formation of political parties, and the first major political party in Nigeria was the Nigerian National Democratic Party (NNDP), founded by Herbert Macaulay in 1923.', 'Emergence of Political Parties', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which newspaper, founded by Nnamdi Azikiwe, became an influential platform for advocating nationalism and political reform in Nigeria?', '["The West African Pilot", "The Daily Times", "The Nigerian Tribune", "The Guardian"]'::jsonb, 0, 'Among the most influential newspapers was the West African Pilot, founded by Nnamdi Azikiwe, which became a powerful platform for advocating nationalism and political reform.', 'Rise of Nigerian Nationalism', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Sir Bernard Bourdillon''s 1939 administrative reform divided the former Southern Provinces into the Eastern and Western Provinces using which natural boundary?', '["The River Niger", "The River Benue", "The Sahara Desert edge", "The Atlantic coastline"]'::jsonb, 0, 'In 1939, Bourdillon divided the former Southern Provinces into two administrative regions using the River Niger as the boundary, resulting in the emergence of the Eastern and Western Provinces, distinguishing the Igbo-dominated East from the Yoruba-dominated West.', 'Bourdillon''s Administrative Reforms', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Richards Constitution of 1946, introduced by Sir Arthur Richards, achieved which of the following for the first time?', '["It brought Northern and Southern Nigeria under a common legislative framework", "It granted Nigeria full independence", "It abolished all regional legislatures", "It removed the income qualification for voting entirely"]'::jsonb, 0, 'The Richards Constitution brought Northern and Southern Nigeria under a common legislative framework for the first time, while also establishing regional legislatures and reducing the income qualification for electoral participation from £100 to £50.', 'The Richards Constitution of 1946', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Under the Richards Constitution, which governor succeeded Sir Arthur Richards in 1948 and adopted a more consultative approach to constitutional reform?', '["Sir John Macpherson", "Sir Hugh Clifford", "Sir Bernard Bourdillon", "Sir Frederick Lugard"]'::jsonb, 0, 'Sir John Macpherson succeeded Sir Arthur Richards as Governor of Nigeria in 1948, and learning from the criticisms directed at the Richards Constitution, adopted a more consultative approach that led to the Macpherson Constitution of 1951.', 'The Macpherson Constitution of 1951', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What year did the Macpherson Constitution come into effect in Nigeria?', '["1946", "1951", "1954", "1960"]'::jsonb, 1, 'The Macpherson Constitution, drafted after nationwide consultations, came into effect in 1951, expanding Nigerian participation in government.', 'Macpherson Constitution', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Under the Macpherson Constitution, which region was given only a unicameral House of Assembly instead of a bicameral legislature?', '["Northern Region", "Western Region", "Eastern Region", "Lagos Colony"]'::jsonb, 2, 'The Northern and Western Regions received bicameral legislatures (House of Assembly and House of Chiefs), while the Eastern Region had only a unicameral House of Assembly.', 'Macpherson Constitution', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which political party was dominant in Northern Nigeria under the regional politics that emerged during the Macpherson Constitution era?', '["Action Group (AG)", "National Council of Nigeria and the Cameroons (NCNC)", "Northern People''s Congress (NPC)", "National Party of Nigeria (NPN)"]'::jsonb, 2, 'The Northern People''s Congress (NPC) was dominant in the North, while the Action Group (AG) was strong in the West and the NCNC was influential in the East.', 'Macpherson Constitution', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In 1953, which Nigerian legislator moved a motion in the federal legislature calling for self-government in 1956?', '["Chief Obafemi Awolowo", "Chief Anthony Enahoro", "Sir Ahmadu Bello", "Dr Nnamdi Azikiwe"]'::jsonb, 1, 'Chief Anthony Enahoro moved the 1953 motion calling for self-government by 1956, which was opposed by Northern representatives and led to political tension.', 'Macpherson Constitution', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Lyttleton Constitution of 1954 formally established Nigeria as what type of state?', '["A unitary state", "A federal state", "A republic", "A confederation"]'::jsonb, 1, 'The Lyttleton Constitution of 1954 formally established Nigeria as a federal state, dividing legislative powers between federal and regional governments.', 'Lyttleton Constitution', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Under the Lyttleton Constitution, legislative powers were divided into the Exclusive Legislative List, the Concurrent Legislative List, and which other category?', '["Emergency Powers", "Residual Powers", "Reserved Powers", "Delegated Powers"]'::jsonb, 1, 'The Lyttleton Constitution divided powers into the Exclusive Legislative List, Concurrent Legislative List, and Residual Powers, giving regions considerable autonomy while preserving national unity.', 'Lyttleton Constitution', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which regions of Nigeria achieved internal self-government in 1957 under the Lyttleton Constitution framework?', '["Northern and Western Regions", "Eastern and Northern Regions", "Eastern and Western Regions", "All three regions simultaneously"]'::jsonb, 2, 'The Eastern and Western Regions achieved internal self-government in 1957, while the Northern Region attained self-government later, in 1959.', 'Lyttleton Constitution', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Willink Commission was established in 1957 to investigate what issue?', '["Corruption in regional governments", "The fears of minority ethnic groups about domination", "The boundaries of the new federal capital", "Electoral fraud in regional elections"]'::jsonb, 1, 'The British government set up the Willink Commission in 1957, chaired by Sir Henry Willink, to investigate the fears of minority ethnic groups that they might be dominated by larger groups within the regions.', 'Willink Commission', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What did the Willink Commission ultimately recommend regarding the demands of minority groups?', '["The creation of new states for minorities", "Constitutional safeguards rather than new states", "Complete regional independence", "Dissolution of the regions"]'::jsonb, 1, 'Rather than creating new states, the Willink Commission recommended constitutional safeguards to address the genuine fears expressed by minority communities.', 'Willink Commission', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'On what date did Nigeria gain independence from Britain?', '["1 October 1960", "1 October 1963", "15 January 1966", "29 May 1999"]'::jsonb, 0, 'Nigeria gained independence on 1 October 1960, following the Nigerian Independence Act of 1960 passed by the British Parliament.', 'Independence Constitution 1960', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Under the Independence Constitution of 1960, who became Nigeria''s Governor-General?', '["Sir Abubakar Tafawa Balewa", "Dr Nnamdi Azikiwe", "Chief Obafemi Awolowo", "Sir James Robertson"]'::jsonb, 1, 'Dr Nnamdi Azikiwe became Governor-General under the Independence Constitution, while Sir Abubakar Tafawa Balewa became Prime Minister and Head of Government.', 'Independence Constitution 1960', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Nigeria became a Federal Republic within the Commonwealth on what date?', '["1 October 1960", "1 October 1963", "15 January 1966", "1 October 1979"]'::jsonb, 1, 'The Republican Constitution came into effect on 1 October 1963, making Nigeria a Federal Republic and abolishing the office of Governor-General.', 'Republican Constitution 1963', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Who became Nigeria''s first President under the Republican Constitution of 1963?', '["Sir Abubakar Tafawa Balewa", "Dr Nnamdi Azikiwe", "General Yakubu Gowon", "Chief Obafemi Awolowo"]'::jsonb, 1, 'Dr Nnamdi Azikiwe became Nigeria''s first President in 1963, while Sir Abubakar Tafawa Balewa remained Prime Minister and Head of Government.', 'Republican Constitution 1963', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In a republic, as described in the context of Nigeria''s First Republic, how is leadership typically determined?', '["Through hereditary succession", "Through periodic elections by citizens exercising power via elected representatives", "Through appointment by a colonial governor", "Through military selection"]'::jsonb, 1, 'A republic is a form of government in which supreme political authority resides with citizens, who exercise this power through elected representatives chosen in periodic elections rather than hereditary succession.', 'First Republic', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Dr Nnamdi Azikiwe, popularly known as "Zik of Africa," hailed from which present-day state?', '["Anambra State", "Bayelsa State", "Plateau State", "Ogun State"]'::jsonb, 0, 'Dr Nnamdi Azikiwe (1904-1996) hailed from Nnewi in present-day Anambra State, though he was born in Zungeru.', 'First Republic Leaders', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The political crisis that deepened divisions in the Action Group during the First Republic centred on rivalry between which two figures?', '["Azikiwe and Balewa", "Chief Obafemi Awolowo and Chief S. L. Akintola", "Gowon and Ironsi", "Ojukwu and Effiong"]'::jsonb, 1, 'Rivalry between Chief Obafemi Awolowo and Chief S. L. Akintola deepened divisions within the Action Group, contributing to the 1965 Western Regional election crisis.', 'Election Crisis and Military Rule', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The violent unrest following the disputed 1965 Western Regional elections, involving arson and political violence, became known by what name?', '["Operation Feed the Nation", "Operation Wet e", "The Kano Riots", "Operation Python Dance"]'::jsonb, 1, 'The 1965 Western Regional election crisis led to the collapse of public order in the Western Region, including political violence known as "Operation Wet e," in which opponents'' houses were set on fire.', 'Election Crisis and Military Rule', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Nigeria''s first military coup took place on what date?', '["15 January 1966", "29 July 1966", "30 May 1967", "13 February 1976"]'::jsonb, 0, 'The first military coup in Nigeria occurred on 15 January 1966, led by a group of young officers popularly known as the "Five Majors."', 'First Military Coup', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which senior political leader was assassinated during the 15 January 1966 coup along with the Premiers of the Northern and Western Regions?', '["Dr Nnamdi Azikiwe", "Sir Abubakar Tafawa Balewa", "General Yakubu Gowon", "Chief Ernest Shonekan"]'::jsonb, 1, 'Prime Minister Sir Abubakar Tafawa Balewa was assassinated in the 15 January 1966 coup, along with Premier Sir Ahmadu Bello of the North and Premier Chief S. L. Akintola of the West.', 'First Military Coup', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Following the January 1966 coup, who was invoked as acting Head of State by the Federal Council of Ministers before the military formally took power?', '["Dr Nwafor Orizu", "General Aguiyi-Ironsi", "General Gowon", "Chief Shonekan"]'::jsonb, 0, 'With the President abroad, the Federal Council of Ministers invoked the constitutional authority of Senate President Dr Nwafor Orizu as acting Head of State before formally relinquishing power to the military.', 'First Military Coup', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Major-General J.T.U. Aguiyi-Ironsi''s controversial Decree No. 34 of May 1966 attempted to do what?', '["Create twelve new states", "Abolish the federal structure and replace it with a unitary system", "Establish a Constitution Drafting Committee", "Introduce the Structural Adjustment Programme"]'::jsonb, 1, 'Aguiyi-Ironsi''s Decree No. 34 of May 1966 sought to abolish Nigeria''s federal structure and replace it with a centralised, unitary system of government, which generated strong opposition, particularly in the North.', 'Aguiyi-Ironsi Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The counter-coup of 29 July 1966 resulted in the deaths of Major-General Ironsi and which other official?', '["Chief Anthony Enahoro", "Lt-Colonel Adekunle Fajuyi, Military Governor of the Western Region", "Chief S.L. Akintola", "Sir Ahmadu Bello"]'::jsonb, 1, 'The July 1966 counter-coup, carried out by Northern military officers, killed both Major-General Ironsi and Lt-Colonel Adekunle Fajuyi, the Military Governor of the Western Region.', 'Counter-Coup of July 1966', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'General Yakubu Gowon, who emerged as Head of State after the July 1966 counter-coup, took which major action regarding Nigeria''s federal structure?', '["He reversed Ironsi''s unitary system and restored federalism", "He abolished the regions entirely", "He declared Nigeria a one-party state", "He annulled the 1965 elections"]'::jsonb, 0, 'Gowon reversed Ironsi''s unitary system, restoring Nigeria to a federal structure, and in 1967 created twelve states from the four existing regions.', 'Gowon Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'On what date did Lt-Colonel Odumegwu Ojukwu proclaim the Eastern Region''s independence as the "Republic of Biafra"?', '["9 August 1966", "30 May 1967", "2 July 1967", "15 January 1970"]'::jsonb, 1, 'Ojukwu, then Military Governor of the Eastern Region, proclaimed the region''s independence as the Republic of Biafra on 30 May 1967, taking over federal installations in the East.', 'Biafra Secession', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Nigerian Civil War lasted from 2 July 1967 until what date?', '["10 January 1970", "15 January 1970", "1 October 1970", "8 June 1970"]'::jsonb, 1, 'The Nigerian Civil War lasted from 2 July 1967 to 15 January 1970, when Biafra''s forces surrendered to the federal government.', 'Nigerian Civil War', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Who formally surrendered Biafra to Nigerian forces after Ojukwu fled the country in January 1970?', '["Major General Philip Effiong", "General Yakubu Gowon", "Colonel Adekunle Fajuyi", "Chief Anthony Enahoro"]'::jsonb, 0, 'After Ojukwu fled with his family, Major General Philip Effiong, Commander of the Biafran Army, consulted the Biafran Strategic Committee and surrendered to Nigerian forces on 10 January 1970.', 'Nigerian Civil War', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What policy did General Gowon initiate after Biafra''s surrender to facilitate post-war recovery, alongside declaring "No Victor, No Vanquished"?', '["Structural Adjustment Programme", "The 3Rs policy: Reconstruction, Reconciliation, and Rehabilitation", "Operation Feed the Nation", "War Against Indiscipline"]'::jsonb, 1, 'Following Biafra''s unconditional surrender, Gowon declared the war "No Victor, No Vanquished" and initiated the 3Rs policy—Reconstruction, Reconciliation, and Rehabilitation—to aid post-war recovery.', 'Nigerian Civil War', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Brigadier Murtala Muhammed became Head of State in July 1975 after a coup that removed which leader?', '["General Aguiyi-Ironsi", "General Yakubu Gowon", "General Olusegun Obasanjo", "General Sani Abacha"]'::jsonb, 1, 'In July 1975, Brigadier Murtala Muhammed emerged as Head of State following a coup that removed General Yakubu Gowon, largely motivated by dissatisfaction with delays in returning Nigeria to civilian rule.', 'Murtala Muhammed Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In February 1976, the Murtala Muhammed administration reorganised Nigeria from twelve states into how many states?', '["Fifteen states", "Nineteen states", "Twenty-one states", "Thirty states"]'::jsonb, 1, 'In February 1976, Nigeria was reorganised from twelve states into nineteen states, further decentralising political power.', 'Murtala Muhammed Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'General Murtala Muhammed was assassinated in a failed coup attempt led by whom, on 13 February 1976?', '["Lt Colonel Buka Suka Dimka", "General Ibrahim Babangida", "Major General Philip Effiong", "Brigadier Tunde Idiagbon"]'::jsonb, 0, 'General Murtala Muhammed''s administration lasted only about six months before he was assassinated in a failed coup attempt led by Lt Colonel Buka Suka Dimka on 13 February 1976.', 'Murtala Muhammed Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'General Olusegun Obasanjo''s Operation Feed the Nation (OFN), launched in the late 1970s, was designed to achieve what goal?', '["Reduce corruption in the civil service", "Encourage agricultural production and reduce dependence on food imports", "Expand the national road network", "Promote adult literacy"]'::jsonb, 1, 'Operation Feed the Nation (OFN) was a key policy initiative under Obasanjo designed to encourage agricultural production and reduce dependence on food imports, promoting self-sufficiency in food production.', 'Obasanjo Administration (1976-1979)', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Who became Nigeria''s first executive President in the Second Republic, following the 1979 elections?', '["Alhaji Shehu Shagari", "General Muhammadu Buhari", "Chief Ernest Shonekan", "General Ibrahim Babangida"]'::jsonb, 0, 'Alhaji Shehu Shagari became Nigeria''s first executive President in the Second Republic (1979-1983), governing under the platform of the National Party of Nigeria (NPN).', 'Second Republic', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What brought an end to Alhaji Shehu Shagari''s Second Republic government?', '["A referendum on the constitution", "A military takeover on 31 December 1983 led by General Muhammadu Buhari", "His voluntary resignation", "Defeat in a general election"]'::jsonb, 1, 'By the end of 1983, political instability and dissatisfaction with governance culminated in a military takeover on 31 December 1983, led by General Muhammadu Buhari and Brigadier Tunde Idiagbon.', 'Second Republic', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'General Muhammadu Buhari''s 1983-1985 administration introduced the "War Against Indiscipline" (WAI), which aimed to promote what?', '["Military recruitment", "Civic responsibility, punctuality, and orderliness in public life", "Foreign investment", "Agricultural exports"]'::jsonb, 1, 'The War Against Indiscipline (WAI) was introduced by the Buhari administration (1983-1985) to promote civic responsibility, punctuality, and orderliness in public life.', 'Buhari Administration (1983-1985)', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'General Buhari''s first administration (1983-1985) was eventually overthrown in a palace coup on 27 August 1985, led by whom?', '["General Sani Abacha", "General Ibrahim Babangida", "General Abdulsalami Abubakar", "Chief Ernest Shonekan"]'::jsonb, 1, 'Despite its anti-corruption efforts, the Buhari administration was criticised for authoritarian practices and was overthrown in a palace coup on 27 August 1985 led by General Ibrahim Babangida.', 'Buhari Administration (1983-1985)', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'General Ibrahim Babangida''s Structural Adjustment Programme (SAP), introduced in 1986, aimed primarily to do what?', '["Increase government spending on the military", "Restructure the Nigerian economy, reduce dependence on oil, and encourage private sector growth", "Nationalise foreign-owned businesses", "Abolish the naira"]'::jsonb, 1, 'The Structural Adjustment Programme (SAP), introduced in 1986, aimed to restructure the Nigerian economy, reduce dependence on oil, and encourage private sector growth, though it also led to inflation and hardship.', 'Babangida Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In 1991, General Babangida moved Nigeria''s capital from Lagos to which city?', '["Kaduna", "Port Harcourt", "Abuja", "Enugu"]'::jsonb, 2, 'In 1991, Babangida moved Nigeria''s capital from Lagos to Abuja, making Abuja the official Federal Capital Territory.', 'Babangida Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The presidential election of 12 June 1993, widely regarded as one of the freest and fairest in Nigeria''s history, was believed to have been won by whom?', '["Chief Ernest Shonekan", "Chief Moshood Kashimawo Olawale (M.K.O.) Abiola", "General Sani Abacha", "Chief Obafemi Awolowo"]'::jsonb, 1, 'The 12 June 1993 election was believed to have been won by Chief M.K.O. Abiola of the Social Democratic Party (SDP), but the military government annulled the results before they were officially concluded.', 'June 12, 1993 Election Crisis', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Following the annulment of the June 12, 1993 election, Babangida handed power to an Interim National Government led by whom?', '["Chief Ernest Shonekan", "General Sani Abacha", "Chief M.K.O. Abiola", "General Abdulsalami Abubakar"]'::jsonb, 0, 'In August 1993, Babangida handed over power to an Interim National Government led by Chief Ernest Shonekan, whose administration was short-lived and faced challenges of legitimacy.', 'Third Republic', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'General Sani Abacha''s regime (1993-1998), widely regarded as authoritarian, was notably associated with the imprisonment of which figure?', '["General Obasanjo", "Chief M.K.O. Abiola, the presumed winner of the 1993 election", "Alhaji Shehu Shagari", "General Babangida"]'::jsonb, 1, 'Abacha''s government imprisoned Chief M.K.O. Abiola, the presumed winner of the annulled 1993 election, which further intensified political tensions.', 'Abacha Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'General Sani Abacha''s administration came to an end following what event on 8 June 1998?', '["A successful coup against him", "His sudden death", "His voluntary resignation", "A national referendum"]'::jsonb, 1, 'Abacha died suddenly on 8 June 1998, bringing an end to his authoritarian administration.', 'Abacha Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'General Abdulsalami Abubakar, who succeeded Abacha in June 1998, is primarily credited with what achievement?', '["Winning the Nigerian Civil War", "Implementing a rapid transition programme leading to democratic elections and a peaceful handover to civilian rule in 1999", "Annulling the June 12 election", "Creating twelve states"]'::jsonb, 1, 'General Abdulsalami Abubakar focused on restoring Nigeria to civilian rule, implementing a rapid transition programme that led to the 1999 elections and a peaceful handover of power on 29 May 1999.', 'Abdulsalami Abubakar Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Chief Olusegun Obasanjo, as civilian President from 1999, established which two anti-corruption agencies?', '["EFCC and ICPC", "INEC and NECO", "NNPC and NDDC", "SEC and CBN"]'::jsonb, 0, 'Obasanjo''s administration established the Economic and Financial Crimes Commission (EFCC) and the Independent Corrupt Practices Commission (ICPC) to combat corruption.', 'Obasanjo Fourth Republic', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What major political issue marked the end of Obasanjo''s tenure as President in the mid-2000s?', '["A failed coup attempt", "An unsuccessful attempt to amend the constitution to allow a third term", "The annulment of the 2003 election", "A declaration of a state of emergency nationwide"]'::jsonb, 1, 'A major political issue of Obasanjo''s tenure was his unsuccessful attempt to amend the constitution to allow himself a third term, which was rejected by the National Assembly.', 'Obasanjo Fourth Republic', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'President Umaru Musa Yar''Adua''s administration (2007-2010) is best known for introducing what policy framework?', '["The Structural Adjustment Programme", "A Seven-Point Agenda focused on power, security, education, agriculture, and infrastructure", "Operation Feed the Nation", "The War Against Indiscipline"]'::jsonb, 1, 'Yar''Adua introduced a Seven-Point Agenda focused on power supply, security, education, agriculture, and infrastructure, and pursued an amnesty programme for Niger Delta militants.', 'Yar''Adua Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'President Yar''Adua died in office on what date, leading to his succession by Vice President Goodluck Jonathan?', '["5 May 2010", "9 February 2010", "29 May 2015", "8 June 1998"]'::jsonb, 0, 'Yar''Adua''s administration was affected by prolonged illness, and he died on 5 May 2010, after which he was succeeded by his Vice President, Goodluck Jonathan.', 'Yar''Adua Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Goodluck Jonathan''s rise to Acting President in February 2010, before Yar''Adua''s death, was made possible through what constitutional principle?', '["The Doctrine of Necessity", "A presidential decree", "A Supreme Court ruling", "A military intervention"]'::jsonb, 0, 'The Doctrine of Necessity, an exceptional constitutional principle applied during institutional paralysis, allowed the National Assembly to empower Vice President Jonathan to act in place of the incapacitated President Yar''Adua on 9 February 2010.', 'Doctrine of Necessity', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Goodluck Jonathan''s Fourth Republic administration is particularly associated with which high-profile corruption scandal?', '["The Dasukigate case", "Operation Wet e", "The Kano disturbances", "The June 12 annulment"]'::jsonb, 0, 'Jonathan''s administration was widely criticised for systemic corruption within government institutions, exemplified by high-profile scandals such as the Dasukigate case.', 'Jonathan Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In the historic 2015 general election, President Goodluck Jonathan set a precedent rare on the African continent by doing what?', '["Postponing the election indefinitely", "Gracefully conceding defeat to Muhammadu Buhari", "Declaring a state of emergency to remain in power", "Annulling the results"]'::jsonb, 1, 'Jonathan gracefully conceded defeat to Muhammadu Buhari of the APC in 2015, a display of political maturity that helped preempt post-election violence and underscored his commitment to national stability.', '2015 General Election', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Independent National Electoral Commission (INEC), under Professor Attahiru Jega, introduced what technology for the 2015 elections?', '["Electronic voting machines", "The Smart Card Reader (SCR) for voter accreditation", "Blockchain-based result transmission", "Biometric national ID cards"]'::jsonb, 1, 'INEC introduced the Smart Card Reader (SCR) technology in 2015 to improve voter accreditation and reduce electoral fraud, though it faced some technical failures.', '2015 General Election', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'President Muhammadu Buhari''s 2015-2023 administration prioritised anti-corruption campaigns under what slogan?', '["\"Renewed Hope\"", "\"Change\"", "\"No Victor, No Vanquished\"", "\"Operation Feed the Nation\""]'::jsonb, 1, 'Buhari returned to power in 2015 under the All Progressives Congress (APC) with a campaign anchored on "Change," prioritising anti-corruption campaigns, security reforms, and economic restructuring.', 'Buhari Fourth Republic', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which insurgency was a major security challenge that persisted throughout Buhari''s 2015-2023 presidency?', '["The Biafran secessionist movement", "The Boko Haram insurgency in the North-East", "The Niger Delta militant uprising", "The Maitatsine riots"]'::jsonb, 1, 'Buhari''s administration contended with escalating violence across multiple regions, including the relentless Boko Haram insurgency in the North-East, alongside banditry and kidnappings in the North-West.', 'Buhari Fourth Republic', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'President Bola Ahmed Tinubu served as Governor of which state from 1999 to 2007 before becoming President in 2023?', '["Ogun State", "Lagos State", "Oyo State", "Rivers State"]'::jsonb, 1, 'Tinubu served as Governor of Lagos State from 1999 to 2007, where he transformed the state''s revenue generation and infrastructure before later becoming President.', 'Tinubu Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Tinubu played a key strategic role in Nigerian politics in 2013 by doing what?', '["Founding the PDP", "Orchestrating the merger of opposition parties to form the All Progressives Congress (APC)", "Leading the National Assembly", "Chairing the Willink Commission"]'::jsonb, 1, 'Tinubu''s strategic genius became evident when he orchestrated the merger of opposition parties to form the All Progressives Congress (APC) in 2013, which went on to defeat the ruling PDP in 2015.', 'Tinubu Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'One of President Tinubu''s most significant and controversial early policy actions after assuming office in 2023 was what?', '["Nationalising the oil industry", "The removal of fuel subsidies", "Re-annexing the Niger Delta", "Abolishing state governments"]'::jsonb, 1, 'Since assuming office, Tinubu implemented bold reforms including the removal of fuel subsidies, which the government argued had become fiscally unsustainable and prone to corruption.', 'Tinubu Administration', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Chinua Achebe''s "The Trouble with Nigeria," what is fundamentally at the root of Nigeria''s central problem?', '["Ethnic diversity", "Leadership", "Colonial boundaries", "Religious differences"]'::jsonb, 1, 'Chinua Achebe argues in "The Trouble with Nigeria" that Nigeria''s central problem is fundamentally rooted in leadership, shaping the country''s political development across its history.', 'Conclusion: Leadership in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to E. B. Tylor''s classic definition (as quoted by Peters and Bailey), culture is best described as what?', '["Only the fine arts of a society", "That complex whole which includes knowledge, belief, art, morals, law, custom, and other capabilities and habits acquired by man as a member of society", "A fixed set of religious rituals", "The economic system of a people"]'::jsonb, 1, 'E. B. Tylor''s classic definition, quoted by Peters and Bailey (1994), describes culture as "that complex whole which includes knowledge, belief, art, morals, law, custom, and any other capabilities and habits acquired by man as a member of society."', 'Definition of Culture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'For Schneider et al., culture can be understood as what kind of pattern?', '["A pattern of basic assumptions people create and learn early in life to help them succeed in internal and external adaptation", "A pattern of trade relationships", "A fixed genetic inheritance", "A single religious doctrine"]'::jsonb, 0, 'Schneider et al. describe culture as the pattern of basic assumptions that people create and learn early in life, which helps them succeed in both internal and external adaptation.', 'Definition of Culture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The word "art" is said to derive from which Latin word, meaning "arrangement"?', '["ars", "artis", "cultura", "ontos"]'::jsonb, 0, 'Etymologically, the word art derives from the Latin word ars, which simply means arrangement, implying that an arrangement cannot be arbitrary but calls imagination and reason into play.', 'Definition of Art', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Nwala (2010), what are the four components of art?', '["The artist, the work of art itself, the spectator/contemplator, and the environment", "The sculptor, the painter, the musician, and the dancer", "Colour, form, texture, and sound", "The buyer, the seller, the critic, and the museum"]'::jsonb, 0, 'Nwala (2010:265) identified four components of art: the artist, the work of art itself, the spectator or contemplator of the work of art, and the environment.', 'Definition of Art', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In pre-colonial Igbo family structure, who was recognised as the head of the family, followed in order by the first son and then the mother?', '["The father", "The eldest daughter", "The village priest", "The oldest woman"]'::jsonb, 0, 'In the pre-colonial Igbo family hierarchy, the father was head of the family, followed by the first son, then the mother, in an organised structure based on Igbo traditional ontology.', 'Igbo Political Organisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In pre-colonial Igbo society, upon the death of the father, who typically became the new leader of the household?', '["The wife of the deceased", "The first son, not the wife of the deceased", "The village council", "The youngest son"]'::jsonb, 1, 'As clarified using Chinua Achebe''s account of Edogo''s homestead, upon the father''s death it was the first son, not the wife of the deceased, who became the leader of the household.', 'Igbo Political Organisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'At the Umunna (kindred) level of pre-colonial Igbo governance, who held the ofo, the symbol of authority?', '["The oldest male descendant of the eldest son of the original founder of the kindred", "Any elected representative", "The village priest alone", "The wealthiest man in the kindred"]'::jsonb, 0, 'At the Umunna level, the oldest male descendant of the eldest son of the kindred''s original founder held the ofo (symbol of authority) and performed the function of okpara (first male).', 'Igbo Political Organisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What was the highest level of leadership in socio-political traditional Igboland, where decisions affecting the whole community were made?', '["Umunna (kindred)", "Ogbe (village)", "Obodo (town unit)", "Ala (earth)"]'::jsonb, 2, 'The obodo (Town Unit) was the highest level of leadership in traditional Igbo society, where the oldest man in the community, the community leader, made decisions at his obi (palace).', 'Igbo Political Organisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The pre-colonial Igbo system of political leadership, in which the oldest man with the ofo held the highest recognised authority, can be summarised as what type of government?', '["A theocracy", "A gerontocracy", "A monarchy", "A democracy"]'::jsonb, 1, 'Because political leadership in traditional Igbo society was tied to being the oldest man holding the ofo, this system of government can be summarised as a gerontocracy.', 'Igbo Political Organisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Nwala (2010), how many objects of Igbo indigenous religion were identified?', '["Three", "Four", "Five", "Seven"]'::jsonb, 2, 'Nwala (2010:166-167) identified five objects of Igbo indigenous religion: the Supreme Being, numerous local deities, the divinity of ancestors, oracles and divination, and numerous abstract forces.', 'Igbo Traditional Religion', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In Igbo traditional cosmology, what were the three tiers of the ordered cosmic structure?', '["The sky (Elu Igwe), the earth (Ala), and the underworld (Ala-mmuo)", "Heaven, hell, and purgatory", "The village, the kindred, and the family", "The past, present, and future"]'::jsonb, 0, 'Traditional Igbo cosmology used ideas of time and space to create a tiered structure: the sky above (Elu Igwe), the solid earth (Ala), and the underworld (Ala-mmuo), all considered inhabited.', 'Igbo Cosmology', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which Igbo deity is described as the sun and was considered the most obvious time marker in the traditional Igbo worldview?', '["Amadioha", "Anyanwu", "Ala", "Chi-Ukwu"]'::jsonb, 1, 'Anyanwu, the Igbo deity of the sun, was considered the most obvious time marker in the traditional Igbo worldview.', 'Igbo Cosmology', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Kalu (2002) argued against the suggestion that Igbo belief in the Supreme Being resulted from what?', '["Contact with Islam", "Encounter with the Christian West", "Trade with the Portuguese", "Colonial administration policies"]'::jsonb, 1, 'Kalu (2002) rejected the suggestion that Igbo belief in the Supreme Being was a result of the Igbo people''s encounter with the Christian West, citing the oral tradition, cosmogonic myths, and personal names as evidence it predated such contact.', 'Igbo Traditional Religion', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Arinze Francis (as cited by Kalu), how many types of sacrifice were identified in Igbo traditional religion?', '["Two", "Three", "Five", "Seven"]'::jsonb, 2, 'Arinze Francis identified five types of sacrifices in Igbo traditional religion: thank-offering, propitiatory, cleansing of abomination, sacrifices to ward off evil spirits, and petition sacrifices.', 'Sacrifice in Igbo Religion', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In pre-colonial Igbo religious practice, what was regarded as "the highest form of ritual atonement available in traditional Igboland" for moral misconduct?', '["Prayer alone", "Ikpu Aru (cleansing of abomination)", "Divination", "Liturgy"]'::jsonb, 1, 'According to Kalu, Ikpu Aru (cleansing of abomination) was considered the highest form of ritual atonement available in traditional Igboland for moral misconduct.', 'Morality in Igbo Religion', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In Igbo traditional religion, what practice was founded on the desire to discern the mind and disposition of the supernatural being and to find out the future?', '["Divination (captured in the concept of Igba Afa)", "Liturgy", "Story-telling", "Architecture"]'::jsonb, 0, 'Divination, captured in the concept of Igba Afa, was founded on man''s quest to discern the mind and disposition of the supernatural being and to find out what the future held.', 'Divination in Igbo Religion', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which arch-divinity was associated with divination in Igbo traditional religion?', '["Amadioha", "Agwu-Nsi", "Anyanwu", "Ala"]'::jsonb, 1, 'Agwu-Nsi was the arch-divinity for divination, and skilled diviners used material objects such as Nkpulu Afa (Afa seeds) in the practice.', 'Divination in Igbo Religion', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Igbo philosophy of hospitality is captured in the adage "oche onye abia kariri nke onye nwe be," which means what?', '["The visitor should sleep separately from the host", "The seat offered to the visitor is always ''higher'' than that of the owner of the house", "Visitors should bring their own food", "A guest must never eat with the host"]'::jsonb, 1, 'The essence of Igbo hospitality is captured in the adage "oche onye abia kariri nke onye nwe be," meaning the seat offered to the visitor is always considered ''higher'' than that of the owner of the house.', 'Igbo Hospitality', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Opata (2002), in Igbo conceptions of time, "oge" as an abstract entity is best described as what?', '["Fixed and measured by a clock", "Inexhaustible and endless", "Determined solely by the seasons", "Identical to Western time"]'::jsonb, 1, 'Opata (2002:13) argued that among the Igbo, as an abstract entity, oge (time) is inexhaustible and endless, captured in the adage "oge anaghi agwu" (time is inexhaustible).', 'Igbo Concept of Time', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The traditional Nsukka Igbo division of the day, as documented using Opata''s data, divided the day into roughly how many parts, approximating the Western 24-hour system?', '["Twelve", "Eighteen", "Twenty-four", "Thirty"]'::jsonb, 2, 'An examination of the Nsukka Igbo calibrations of time shows the day was divided into roughly twenty-four parts, similar to but not as exact as the Western division of the day into twenty-four equal hours.', 'Igbo Concept of Time', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Nwala (2010) defined ogwu, the pre-colonial Igbo concept of medicine, as what?', '["A purely herbal remedy", "Force, vital energy, or mystical power", "A written code of law", "A form of currency"]'::jsonb, 1, 'Nwala (2010:87) defined ogwu as "force, vital energy or mystical power," usually linked with medical, magical, and witchcraft activities among the pre-colonial Igbo.', 'Igbo Medicine', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In the Igbo agricultural origin myth involving Eze Nri, why did yams become associated with male gender and cocoyams with female gender?', '["Because a yam sprouted where God told Eze Nri to bury his son, and a cocoyam sprouted where his daughter was buried", "Because women were forbidden from touching yams", "Because yams were harvested only by men in a seasonal ritual", "Because cocoyams grew only in female-owned farmland"]'::jsonb, 0, 'According to the myth, God told Eze Nri to bury one of his sons and one of his daughters during a famine; a yam sprouted where the son was buried and a cocoyam where the daughter was buried, which is why yams are seen as male crops and cocoyams as female crops.', 'Igbo Agriculture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Uzozie, archaeological excavation of a burial chamber at Igbo-Ukwu yielded bronze artefacts dating from approximately what period?', '["The 9th century A.D.", "The 15th century A.D.", "The 3rd century B.C.", "The 19th century A.D."]'::jsonb, 0, 'Uzozie (2002:482) noted that the excavation of a burial chamber at Igbo-Ukwu yielded bronze artefacts such as bells, elephant tusks, and bronze bells dating from the 9th century A.D., suggesting a long agricultural and technological history.', 'Igbo Agriculture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Oloidi (2011), the word "architecture" was first coined in England in what year?', '["1563", "1613", "1789", "1901"]'::jsonb, 0, 'Oloidi (2011:63) noted that the word was first coined in England in 1563, from the Greek word architekton, meaning a chief craftsman or designer.', 'Pre-Colonial Igbo Architecture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In Igbo architectural planning, the centre of a village or town — often marked by a live pole, ancestral tree, shrine, or grove — was known by several local names, including what?', '["Ilo, ogo, obom, obodo, or otobo", "Umunna, ogbe, obodo", "Ala, elu igwe, ala-mmuo", "Chi, agwu, ndichie"]'::jsonb, 0, 'The symbolic centre of a village or town, around which building masses were organised, was known as ilo, ogo, obom, obodo, or otobo, and was often marked by a live pole, ancestral tree, shrine, or grove.', 'Pre-Colonial Igbo Architecture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In pre-colonial Igboland, how did children typically begin learning the art of house-building?', '["Through formal apprenticeship with master builders only", "Through play, building small structures out of wet sand", "By reading illustrated manuals", "Only after reaching adulthood"]'::jsonb, 1, 'Children in Igboland began learning the art of building from childhood through play, using wet sand to construct small structures, effectively beginning to organise space from a young age.', 'Pre-Colonial Igbo Architecture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In the example from the Orba community, what was the name given to a temporary house built by children during the dry season, using only palm fronds and sticks?', '["Ulo mwa okochi", "Oge mpafu", "Ilo Nkwo", "Obi Eze"]'::jsonb, 0, 'In the Orba community, the dry-season house built by children using only palm fronds and sticks was called ulo mwa okochi, meaning "dry season house."', 'Pre-Colonial Igbo Architecture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Besides architecture, which of the following was identified as another aspect of pre-colonial Igbo art, involving guardians of a community''s history who narrated its cosmogony?', '["Story-telling", "Ide uhie (painting)", "Egwu (music)", "Carving"]'::jsonb, 0, 'Story-telling was practised by elders and griots, who acted as guardians of the past in African traditional societies, narrating the community''s cosmogony and history.', 'Pre-Colonial Igbo Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In pre-colonial Igbo art, "ide uhie" refers to which artistic practice?', '["Carving objects from wood or stone", "The art of adding colour to a surface, such as a human or animal body, a house, or furniture, to make it glorious", "Storytelling by village elders", "The construction of ancestral shrines"]'::jsonb, 1, 'Ide uhie (painting) was the art of adding colour to a surface—whether a human or animal body, a house, a tree, or furniture—to make the object glorious to the eyes.', 'Pre-Colonial Igbo Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Nigeria''s multicultural society comprises how many ethnic groups?', '["Fewer than 50", "About 100", "Over 250", "Exactly 36"]'::jsonb, 2, 'Nigeria is described as a multicultural society with over 250 ethnic groups, diverse languages, traditions, and belief systems that coexist across the country.', 'Arts and Nation Building', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Nation-building, in the context of the arts, is described as involving what?', '["Only formal political communication", "The establishment of political institutions and the creation of a shared sense of identity, belonging, and social cohesion among citizens", "Exclusively military coordination", "The privatisation of cultural industries"]'::jsonb, 1, 'Nation-building involves more than the establishment of political institutions or economic structures; it encompasses the creation of a shared sense of identity, belonging, and social cohesion among citizens, a purpose the arts help serve.', 'Arts and Nation Building', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Art is best defined as the creative expression of what?', '["Only religious devotion", "Human imagination, emotions, and experiences, expressed through media such as painting, music, dance, and sculpture", "Government policy", "Scientific discovery"]'::jsonb, 1, 'Art refers to the creative expression of human imagination, emotions, and experiences, encompassing visual creations such as painting, ideas through various media such as poetry and novels, and performing expressions such as music, dance, and film.', 'Meaning of Art', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Culture is best described as referring to what?', '["Only the fine arts of an elite class", "The total way of life of a people, including beliefs, customs, traditions, language, knowledge systems, and material artefacts that are learned", "A fixed and unchanging set of laws", "Exclusively religious rituals"]'::jsonb, 1, 'Culture is described as referring to the total way of life of a people, including beliefs, customs, traditions, language, knowledge systems, and material artefacts that are learned across generations.', 'Meaning of Culture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which of the following is NOT listed as one of the interconnected elements that make up culture?', '["Language", "Religion", "Value systems", "Rainfall patterns"]'::jsonb, 3, 'Culture is described as consisting of elements such as language, religion, customs and traditions, arts and crafts, food and dress, social institutions, and value systems. Rainfall patterns are not a cultural element.', 'Definition and Elements of Culture', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Deutsch and Folt (1966), nation-building is best described as what?', '["The construction of a national identity through state power", "The migration of people across international borders", "The signing of trade agreements between neighbouring states", "The establishment of a single official religion"]'::jsonb, 0, 'Deutsch and Folt (1966) describe nation-building as the construction of a national identity through the use of state power, aimed at uniting the people within a state.', 'Meaning of Nation-Building', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Erondu and Obasi (2000) view nation-building primarily as what kind of process?', '["Mobilisation of human, financial, and material resources for socio-economic growth", "A purely military exercise to defend borders", "The abolition of all ethnic identities", "A process limited to constitutional amendments"]'::jsonb, 0, 'Erondu and Obasi (2000), as cited in Atake and Dodo (2010), view nation-building as the mobilisation of human, financial, and material resources for socio-economic growth and political development within a nation-state.', 'Meaning of Nation-Building', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The historical development of art in Nigeria is conventionally organised into which three major periods?', '["Ancient, medieval, and modern", "Pre-colonial, colonial, and contemporary", "Stone age, iron age, and digital age", "Traditional, missionary, and republican"]'::jsonb, 1, 'Nigeria''s art history is organised into three major periods: the pre-colonial period, the colonial period, and the contemporary period.', 'Historical Development of Art in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Nok Culture is named after a village located in which Nigerian state?', '["Kaduna State", "Kano State", "Katsina State", "Kebbi State"]'::jsonb, 0, 'The Nok Culture is named after the village of Nok in Kaduna State, where the first terracotta figures associated with the culture were identified in the 1940s.', 'The Nok Civilisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Archaeological evidence places the Nok civilisation approximately within which timeframe?', '["500 BC to AD 200", "AD 1000 to AD 1500", "300 BC to 100 BC", "AD 800 to AD 1200"]'::jsonb, 0, 'Archaeological evidence places the Nok civilisation approximately between 500 BC and AD 200, though some scholars suggest the broader tradition may extend earlier.', 'The Nok Civilisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Beyond their artistic value, Nok terracotta sculptures are also significant because they provide evidence of what?', '["Early iron smelting in sub-Saharan Africa", "The first use of the wheel in Nigeria", "Contact with ancient Rome", "The invention of paper-making"]'::jsonb, 0, 'The Nok sculptures provide important archaeological evidence of early iron smelting, indicating that the Nok people were among the earliest iron-using societies in sub-Saharan Africa.', 'The Nok Civilisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Igbo-Ukwu civilisation, located in present-day Anambra State, is dated by radiocarbon dating (Shaw, 1970) to approximately which century?', '["The ninth century AD", "The third century BC", "The fifteenth century AD", "The nineteenth century AD"]'::jsonb, 0, 'The Igbo-Ukwu civilisation flourished around the ninth century AD, as established by radiocarbon dating carried out by Thurstan Shaw.', 'The Igbo-Ukwu Civilisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'What advanced metalworking technique did the Igbo-Ukwu civilisation use to produce its bronze and copper-alloy objects?', '["The lost-wax (cire perdue) casting technique", "Cold hammering", "Sand casting", "Electroplating"]'::jsonb, 0, 'Igbo-Ukwu artefacts were produced using the lost-wax (cire perdue) casting technique, an advanced process involving a wax model encased in clay that is melted away before molten metal is poured in.', 'The Igbo-Ukwu Civilisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Who led the archaeological excavations at Igbo-Ukwu in the late 1950s and 1960s?', '["Thurstan Shaw", "Frank Willett", "Ekpo Eyo", "Kenneth Murray"]'::jsonb, 0, 'The Igbo-Ukwu excavations that uncovered extraordinary collections of bronze and copper-alloy objects were led by Thurstan Shaw.', 'The Igbo-Ukwu Civilisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Ife civilisation, located in present-day Osun State, flourished between which centuries?', '["The twelfth and fifteenth centuries AD", "The fifth and eighth centuries AD", "The seventeenth and nineteenth centuries AD", "The first and third centuries AD"]'::jsonb, 0, 'The Ife civilisation flourished between the twelfth and fifteenth centuries AD, though its artistic and cultural traditions have deeper roots.', 'The Ife Civilisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Early European observers were so astonished by the naturalism of Ife art that they initially and wrongly attributed its influence to which civilisations?', '["Ancient Greece or Egypt", "Ancient China or India", "The Roman Empire", "Ancient Persia"]'::jsonb, 0, 'Ife art''s accurate representation of human anatomy so astonished early European observers that it was initially misattributed to influence from ancient Greece or Egypt, before later research established it as an independent African tradition.', 'The Ife Civilisation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In the Benin Kingdom, the royal guild of brass-casters who produced plaques, ivory tusks, and figurative sculptures is known by what name?', '["Igun Eronmwon", "Ogboni", "Oyo Mesi", "Egungun"]'::jsonb, 0, 'The Benin royal guild of brass-casters, known as Igun Eronmwon, worked under the direct patronage of the Oba and has continued the tradition to the present day.', 'The Benin Kingdom', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Benin''s artistic production, in present-day Edo State, reached its zenith between which centuries?', '["The thirteenth and seventeenth centuries", "The eighteenth and twentieth centuries", "The eighth and tenth centuries", "The second and fourth centuries"]'::jsonb, 0, 'Benin''s artistic production reached its zenith between the thirteenth and seventeenth centuries, producing one of the most celebrated royal art traditions in African history.', 'The Benin Kingdom', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Ancient rock paintings and engravings dating back over a thousand years have been documented at Birnin Kudu, located in which state?', '["Jigawa State", "Sokoto State", "Borno State", "Plateau State"]'::jsonb, 0, 'Ancient rock paintings and engravings have been documented at Birnin Kudu in present-day Jigawa State, dating back over a thousand years in some cases.', 'Other Pre-Colonial Artistic Traditions', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Uli artistic tradition of body and wall painting, characterised by elegant linear designs, was practised chiefly by whom?', '["Igbo women", "Hausa-Fulani emirs", "Benin brass-casters", "Yoruba priests"]'::jsonb, 0, 'The Uli artistic tradition of body and wall painting, developing a sophisticated visual vocabulary of linear designs and symbolic motifs, was practised by Igbo women.', 'Other Pre-Colonial Artistic Traditions', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Zaria Art Society, a major milestone in Nigerian art history, was established between which years?', '["1958 and 1961", "1900 and 1905", "1970 and 1975", "1945 and 1950"]'::jsonb, 0, 'The Zaria Art Society was established between 1958 and 1961 at the Nigerian College of Arts, Science and Technology, Zaria.', 'Colonial Period Art in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Zaria Art Society advocated a philosophy that encouraged artists to integrate African cultural values with modern artistic techniques. What was this philosophy called?', '["Natural Synthesis", "Cultural Revivalism", "Pan-African Modernism", "Afro-Futurism"]'::jsonb, 0, 'The Zaria Art Society, led by pioneers such as Uche Okeke and Demas Nwoko, advocated the philosophy of Natural Synthesis, blending African cultural values with modern artistic techniques.', 'Colonial Period Art in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The 1897 British Punitive Expedition to Benin resulted in the removal of thousands of artefacts, but ironically also had what effect?', '["It introduced Benin art to the international community and boosted its global recognition", "It ended all further study of Nigerian art", "It destroyed the lost-wax casting technique permanently", "It caused the Benin Kingdom to abandon bronze casting entirely"]'::jsonb, 0, 'Although the 1897 Punitive Expedition represented a profound cultural loss for Nigeria, it also introduced Benin art to the international community, ironically helping establish Nigerian art among the finest examples of African art.', 'Colonial Period Art in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The contemporary period of Nigerian art is generally described as spanning from which decade to the present?', '["The 1970s", "The 1920s", "The 1950s", "The 1990s"]'::jsonb, 0, 'The contemporary period of Nigerian art spans from the 1970s to the present, marked by unprecedented growth, diversification, and internationalisation.', 'Contemporary Period of Nigerian Art', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Oloidi (2007), art may broadly be classified into which three major dimensions?', '["Visual arts, literary arts, and performing arts", "Sacred arts, secular arts, and folk arts", "Rural arts, urban arts, and digital arts", "Classical arts, modern arts, and postmodern arts"]'::jsonb, 0, 'Oloidi (2007) classifies art broadly into three major dimensions: visual arts, literary arts, and performing arts, each with distinctive characteristics.', 'Major Dimensions of Art', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Nigerian contemporary artists such as El Anatsui, Njideka Akunyili Crosby, and Emeka Ogboh are noted for engaging with which range of themes?', '["National identity, gender, environmental sustainability, and diaspora experience", "Only ancient mythology", "Exclusively sports culture", "Only agricultural techniques"]'::jsonb, 0, 'Contemporary Nigerian art addresses concerns such as national identity, gender, environmental sustainability, governance, migration, and diaspora, with artists like El Anatsui and Emeka Ogboh achieving international recognition.', 'Contemporary Period of Nigerian Art', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'A defining characteristic of visual arts, distinguishing them from performing arts, is that they produce what?', '["Tangible material works that can be preserved and appreciated across generations", "Sound-based compositions only", "Purely oral traditions", "Temporary events with no lasting record"]'::jsonb, 0, 'A defining characteristic of visual arts is that they produce tangible material works that can be observed, displayed, preserved, and appreciated across generations, unlike the ephemeral nature of performing arts.', 'Visual Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which of the following Nigerian visual artists is specifically noted for her work in pottery/ceramics among the distinguished artists listed?', '["Ladi Kwali", "Wole Soyinka", "Chinua Achebe", "Fela Anikulapo Kuti"]'::jsonb, 0, 'Ladi Kwali is listed among Nigeria''s distinguished visual artists whose works have earned international recognition, known particularly for her ceramics.', 'Visual Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Literary arts are described as creative expressions in which the principal medium for communicating ideas and human experiences is what?', '["Language, whether spoken or written", "Colour and line", "Rhythm and dance movement alone", "Architecture and space"]'::jsonb, 0, 'Literary arts are creative expressions in which language, spoken or written, is the principal medium for communicating ideas, emotions, imagination, and human experiences.', 'Literary Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Chinua Achebe''s novel Things Fall Apart, published in 1958, is notable for what achievement?', '["Being translated into more than sixty languages and remaining a widely studied African literary work", "Being the first Nigerian film to win an international award", "Introducing the Zaria Art Society''s philosophy", "Being written entirely in the Igbo language"]'::jsonb, 0, 'Chinua Achebe''s Things Fall Apart (1958) has been translated into more than sixty languages and remains one of the most widely studied African literary works.', 'Nigerian Literary Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In what year did Wole Soyinka become the first African to win the Nobel Prize in Literature?', '["1986", "1958", "1999", "1970"]'::jsonb, 0, 'Wole Soyinka became the first African to win the Nobel Prize in Literature in 1986, with works reflecting Yoruba culture, philosophy, and mythology.', 'Nigerian Literary Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Flora Nwapa holds which distinction in Nigerian literary history?', '["Nigeria''s first internationally published female novelist", "The first Nigerian to win the Nobel Prize in Literature", "The founder of the Zaria Art Society", "The first female Oba of Benin"]'::jsonb, 0, 'Flora Nwapa was Nigeria''s first internationally published female novelist and helped advance women''s voices in African literature.', 'Nigerian Literary Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Unlike visual arts, which produce enduring objects, performing arts are fundamentally described as what kind of art form?', '["Time-based, existing as events and encounters rather than permanent artefacts", "Permanently preserved physical structures", "Written texts stored in archives", "Static displays in museums"]'::jsonb, 0, 'Performing arts are fundamentally time-based; unlike visual arts (which produce persisting objects) or literary arts (whose texts endure), performing arts are events and encounters realised through live performance.', 'Performing Arts', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'By volume of annual output, the Nigerian film industry (Nollywood) is often described as the world''s what?', '["Second-largest film industry, after India''s Bollywood", "Largest film industry, ahead of Hollywood", "Third-largest, behind Hollywood and Bollywood", "Smallest among major African film industries"]'::jsonb, 0, 'Nollywood, by volume of annual output, is the world''s second-largest film industry after India''s Bollywood, producing thousands of titles annually.', 'Performing Arts and the Creative Economy', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Nigeria is described as home to how many ethnic groups when discussing the arts'' role in nation-building?', '["Over 250 ethnic groups", "About 20 ethnic groups", "Exactly 36 ethnic groups", "Over 1,000 ethnic groups"]'::jsonb, 0, 'In discussing arts and nation-building, Nigeria is described as a culturally diverse country with over 250 ethnic groups coexisting, each with distinct languages, customs, and religious traditions.', 'Arts and Nation Building in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Ololo (2016), Chinua Achebe''s Things Fall Apart asserted the complexity and dignity of pre-colonial African civilisation at what pivotal moment?', '["The very moment Nigeria was moving toward independence", "During the Nigerian Civil War", "After the 1897 Punitive Expedition", "During the amalgamation of 1914"]'::jsonb, 0, 'Things Fall Apart (1958) asserted the complexity and dignity of pre-colonial African civilisation at the very moment Nigeria was moving toward independence, strengthening national consciousness.', 'Arts and National Identity Formation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which of the following is one of the cultural festivals mentioned as promoting intercultural understanding in Nigeria?', '["The Argungu Fishing Festival", "The Calabar Boat Regatta of ancient Rome", "The Zaria Art Biennale", "The Lagos Marathon"]'::jsonb, 0, 'Cultural festivals such as the Argungu Fishing Festival, the Osun-Osogbo Festival, the New Yam Festival, and the Durbar Festival are cited as promoting intercultural understanding among Nigerians and international audiences.', 'Arts and National Identity Formation', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Nollywood''s estimated annual film output and revenue are cited as approximately what figures?', '["About 2,500 films per year, generating roughly $600 million annually", "About 100 films per year, generating $10 million annually", "About 10,000 films per year, generating $5 billion annually", "About 500 films per year, generating $50 million annually"]'::jsonb, 0, 'Nollywood is cited as producing an estimated 2,500 films per year and generating revenues of approximately $600 million annually, according to UNESCO Institute for Statistics and Encyclopaedia Britannica data.', 'Arts and Economic Development', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which cultural site in Lagos is named as a key cultural attraction supporting Nigeria''s tourism industry?', '["The National Museum in Lagos", "The Zaria Art Society headquarters", "The Nok Culture Institute", "The Benin Royal Palace Annex"]'::jsonb, 0, 'The National Museum in Lagos, along with Benin cultural heritage sites, Igbo-Ukwu archaeological discoveries, and the Osun-Osogbo Sacred Grove, is named as a valuable tourism asset for Nigeria.', 'Arts and Tourism Development', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which two Nigerian public figures are cited as examples of artists and writers who used their work to challenge corruption and political injustice?', '["Fela Anikulapo-Kuti and Ken Saro-Wiwa", "Ladi Kwali and El Anatsui", "Flora Nwapa and Ben Enwonwu", "Hubert Ogunde and Bruce Onobrakpeya"]'::jsonb, 0, 'Fela Anikulapo-Kuti, through Afrobeat music, and Ken Saro-Wiwa, through his writing on the Niger Delta, are cited as artists whose work challenged corruption and highlighted complex political issues.', 'Arts and Political Awareness', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The concept that countries can influence others through the attractiveness of their culture and values, rather than hard military power, is known as what, as defined by Nye (2004)?', '["Soft power", "Hard power", "Cultural hegemony", "Diplomatic immunity"]'::jsonb, 0, 'Nye (2004) defines soft power as the means to success in world politics through the appeal of a country''s culture and values, rather than through coercion or hard power.', 'Arts and International Relations', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to PricewaterhouseCoopers projections, Nigeria''s creative industry contribution was estimated to grow to how much by 2025, versus a starting contribution described as inadequately funded?', '["From $6.4 billion toward a potential $15 billion", "From $60 million toward $150 million", "From $600 billion toward $1.5 trillion", "From $6.4 million toward $15 million"]'::jsonb, 0, 'PricewaterhouseCoopers estimated Nigeria''s creative industry contribution at $6.4 billion, with potential growth to $15 billion by 2025, growth that inadequate funding and investment strikingly hinder.', 'Challenges Facing the Arts Sector in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The piracy rate in Nollywood''s digital content is estimated at approximately what percentage?', '["90%", "10%", "50%", "25%"]'::jsonb, 0, 'The Nigerian Copyright Commission has estimated the piracy rate in Nollywood at approximately 90%, contributing to billions of naira in annual losses.', 'Copyright Violations and Piracy', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Akanbi et al. (2023), Nigeria loses approximately how much annually in potential economic output due to the brain drain of creative professionals?', '["$2.5 billion", "$25 million", "$250 billion", "$25 billion"]'::jsonb, 0, 'According to Akanbi et al. (2023), Nigeria loses approximately $2.5 billion annually in potential economic output due to the migration of highly skilled creative professionals abroad.', 'Brain Drain in the Creative Sector', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Investment in the arts should be recognised as what, rather than merely cultural expenditure?', '["An investment in national development", "A luxury the government cannot afford", "A purely private-sector responsibility", "An outdated colonial-era practice"]'::jsonb, 0, 'Investment in the arts should be recognised as an investment in national development rather than merely cultural expenditure, in order to unlock the sector''s full potential.', 'Strategies for Enhancing the Role of Arts in Nation Building', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which strategy involves establishing spaces for artists, writers, designers, musicians, and digital innovators to collaborate, receive mentorship, and access technology?', '["Developing Creative Hubs", "Increasing Government Investment", "Protecting Intellectual Property Rights", "Improving Art Education"]'::jsonb, 0, 'Developing Creative Hubs is the strategy that involves establishing spaces across the country for collaboration, mentorship, training, and entrepreneurship among artists and digital innovators.', 'Strategies for Enhancing the Role of Arts in Nation Building', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Effective enforcement of copyright laws, which reduces piracy and ensures creators receive proper recognition and rewards, falls under which recommended strategy?', '["Protecting Intellectual Property Rights", "Supporting Digital Creativity", "Promoting Cultural Tourism", "Encouraging Private Sector Participation"]'::jsonb, 0, 'Protecting Intellectual Property Rights is the strategy focused on effective enforcement of copyright laws to reduce piracy and ensure creators receive appropriate recognition and financial rewards.', 'Strategies for Enhancing the Role of Arts in Nation Building', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'A study of human rights and social justice in modern and traditional societies gives special attention to the traditional practices of which Nigerian ethnic group as a case study?', '["The Igbo", "The Yoruba", "The Hausa-Fulani", "The Ijaw"]'::jsonb, 0, 'Human rights and social justice discussions focused on modern and traditional societies commonly use the Igbo experience as a case study of traditional human rights practice.', 'Human Rights and Social Justice: Introduction', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'N.S.S. Iwe (1980) observed that history reveals humanity''s tussles to secure what set of values?', '["Freedom, liberty, independence, social justice, and peace", "Territorial expansion and conquest", "Religious uniformity", "Technological supremacy"]'::jsonb, 0, 'N.S.S. Iwe (1980) observed that history books reveal remarkable records of humanity''s attempts to secure freedom, liberty, independence, social justice, and peace, often against oppressive forces.', 'Human Rights and Social Justice: Introduction', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Human rights differ from other kinds of rights in three key respects. Which of the following is one of them?', '["They are inherent, belonging to all humans by virtue of their humanity alone", "They must be purchased from the state", "They apply only to citizens of wealthy nations", "They can be legally granted or revoked at will by any authority"]'::jsonb, 0, 'Human rights are described as inherent (belonging to all by virtue of humanity, not purchased or granted), inalienable within qualified legal bounds, and universal and equal, applying to all persons without discrimination.', 'Defining Human Rights', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to Chukwudozie (1999), fundamental human rights are best understood as what?', '["The moral property of the individual, not a gift from government", "A privilege extended only to law-abiding citizens", "A reward for military service", "An entitlement created solely by international treaties"]'::jsonb, 0, 'Chukwudozie (1999) argues that fundamental human rights are rooted in the intrinsic dignity of the human person and are the moral property of the individual, not a gift from the government.', 'Defining Human Rights', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Article 1 of the Universal Declaration of Human Rights states that all human beings are born how?', '["Free and equal in dignity and rights", "Subject to the authority of the state", "Into predetermined social classes", "With rights that must be earned"]'::jsonb, 0, 'Article 1 of the Universal Declaration of Human Rights states: ''All human beings are born free and equal in dignity and rights. They are endowed with reason and conscience and should act towards one another in the spirit of brotherhood.''', 'Defining Human Rights', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Thomas Aquinas, in the Summa Theologica, defines justice as what?', '["The constant and perpetual will to render to everyone what is due to him", "The power of the state over its citizens", "A privilege reserved for the ruling class", "The absence of law entirely"]'::jsonb, 0, 'Thomas Aquinas defines justice in the Summa Theologica as ''the constant and perpetual will to render to everyone what is due to him.''', 'The Concept of Social Justice', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Social injustice occurs when what condition is present?', '["The principle of equal opportunity is violated and resources are monopolised by a few who exploit the labour of the majority", "Everyone in society has equal access to resources", "Laws are applied consistently to all citizens", "Communities freely participate in decision-making"]'::jsonb, 0, 'Social injustice occurs when the principle of equal opportunity is violated, discrimination exists among groups, and resources meant for the common good are monopolised by a few who exploit the labour of the majority.', 'The Concept of Social Justice', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which theory holds that human rights arise from nature itself and are discernible through reason?', '["Natural Law Theory", "Theological or Divine Origin Theory", "Social Contract Theory", "Positivist Legal Theory"]'::jsonb, 0, 'Natural Law Theory maintains that human rights arise from nature itself, given by the fact of being human, and are discernible through reason — for instance, the right to life is seen as natural.', 'Origins and Philosophical Foundation of Human Rights', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Theological or Divine Origin Theory of human rights cites which biblical example to illustrate the sacredness of life?', '["God''s condemnation of Cain for killing Abel", "The parting of the Red Sea", "The building of the Tower of Babel", "The story of Noah''s Ark"]'::jsonb, 0, 'The Theological Theory holds that human rights originate from God, illustrated in Christianity by God''s condemnation of Cain for killing Abel (Genesis 4) as evidence of the sacredness of life.', 'Origins and Philosophical Foundation of Human Rights', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Magna Carta of 1215 is historically significant for establishing which principle?', '["That the power of the monarch was subject to the law", "That all citizens have the right to vote", "That slavery should be abolished", "That women should have equal property rights"]'::jsonb, 0, 'The Magna Carta (1215) established the principle that the power of the monarch was subject to the law, laying the foundation for the rule of law and protection of individual liberties.', 'Contributions of Revolutions and International Developments', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The American Declaration of Independence (1776) proclaimed that all men are created equal and endowed with which unalienable rights?', '["Life, liberty, and the pursuit of happiness", "Property, taxation, and representation", "Speech, religion, and assembly only", "Trade, commerce, and industry"]'::jsonb, 0, 'The American Declaration of Independence (1776) proclaimed that all men are created equal and endowed with certain unalienable rights, including life, liberty, and the pursuit of happiness.', 'Contributions of Revolutions and International Developments', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which historical developments are cited as having expanded the human rights discourse to emphasise economic justice, social welfare, and workers'' rights?', '["The Communist Manifesto (1847) and the Russian Revolution (1917)", "The Magna Carta (1215) and the English Bill of Rights (1689)", "The French Declaration of the Rights of Man (1789) alone", "The American Declaration of Independence (1776) alone"]'::jsonb, 0, 'The Communist Manifesto (1847) and the Russian Revolution (1917) are cited as having expanded human rights discourse by emphasising economic justice, social welfare, and the rights of workers.', 'Contributions of Revolutions and International Developments', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Nweze (1997) classifies the right to life, dignity, liberty, and freedom of movement under which category of human rights?', '["Personal Rights", "Proprietary Rights", "Procedural Rights", "Equality Rights"]'::jsonb, 0, 'Nweze (1997) classifies rights such as the right to life, dignity, liberty, and freedom of movement under the category of Personal Rights.', 'Classification of Human Rights', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Freedom of expression, freedom of association and assembly, and freedom of conscience and religion fall under which category of human rights, per Nweze''s classification?', '["Political and Moral Rights", "Personal Rights", "Proprietary Rights", "Procedural Rights"]'::jsonb, 0, 'Nweze (1997) classifies freedom of expression, freedom of association and assembly, and freedom of conscience and religion under Political and Moral Rights.', 'Classification of Human Rights', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which of these is listed as a non-governmental organisation working to promote and safeguard human rights?', '["Amnesty International", "The UN Security Council", "The International Court of Justice", "The European Court of Human Rights"]'::jsonb, 0, 'Amnesty International, along with Human Rights Watch and Red Cross International, is listed as a non-governmental organisation (as opposed to the intergovernmental bodies like the UN Security Council or the ICJ) promoting and safeguarding human rights.', 'Agencies for the Promotion and Safeguarding of Human Rights', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which of the following is a Nigerian human rights organisation named among the country''s notable human rights bodies?', '["The National Human Rights Commission (NHRC)", "The World Council of Churches", "Amnesty International", "The International Labour Organisation"]'::jsonb, 0, 'The National Human Rights Commission (NHRC) is listed among Nigeria''s notable human rights organisations, alongside bodies such as SERAP, CDD, and HRAN.', 'Human Rights Agencies in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In traditional Igbo cosmology, the visible world and the invisible spiritual world are respectively known by which terms?', '["Alammadu and Alamuo", "Chukwu and Ani", "Igbo enwe eze and omenala", "Nso ala and aru"]'::jsonb, 0, 'Traditional Igbo cosmology recognises two interconnected orders: the visible world (Alammadu) and the invisible spiritual world (Alamuo), with human existence understood within relationships spanning both.', 'Cosmological Foundation of Igbo Human Rights', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Igbo proverb ''ofu aka lutara mmanu, ozuo aka nile'' (''when one finger collects oil, it spills to the other fingers'') expresses which principle?', '["Interdependence that ensures social harmony, justice, and peace", "The importance of individual wealth accumulation", "The supremacy of a single ruler", "The isolation of the individual from the community"]'::jsonb, 0, 'This proverb expresses the interdependence at the heart of Igbo social justice — that every action reverberates through the web of relationships in the community, ensuring social harmony and peace.', 'Cosmological Foundation of Igbo Human Rights', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In traditional Igbo society, the sacred staff symbolising truth, justice, and moral uprightness is called what?', '["Ofo", "Ikenga", "Ala", "Oji"]'::jsonb, 0, 'The Ofo, a sacred staff typically carved from the Ofo tree (Detarium senegalense or Detarium elastica), symbolises truth, justice, fairness, and moral uprightness in traditional Igbo society.', 'Justice and Equity in Traditional Igbo Society', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The complementary Igbo ethical principle pairing justice with innocence, forming the foundation of traditional Igbo morality, is known as what?', '["Ofo na Ogu", "Igbo enwe eze", "Nso ala", "Omenala"]'::jsonb, 0, 'Igbo cosmology developed the complementary principle of Ofo na Ogu (justice and innocence), which constitutes the ethical foundation of traditional Igbo society, underpinning values like truthfulness and integrity.', 'Justice and Equity in Traditional Igbo Society', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'According to the table of Ofo types in traditional Igbo governance, who typically holds the ''Ofo alusi'' and over what kind of matters?', '["A priest of a deity, over religious matters", "A town elder, over community-wide disputes", "A titled man, over status-related adjudication", "A clan head, over lineage matters"]'::jsonb, 0, 'The Ofo alusi is held by a priest of a deity and governs jurisdiction over religious matters, reflecting the decentralised, multi-institutional nature of Igbo justice administration.', 'Justice and Equity in Traditional Igbo Society', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In traditional Igbo society, how was the taking of a life typically addressed, in contrast to Western legal systems?', '["Through severe restitution such as a seven-year exile or a replacement marriage, rather than capital punishment", "Through immediate capital punishment, as in Western legal systems", "Through complete forgiveness with no consequence", "Through banishment of the victim''s entire family"]'::jsonb, 0, 'Unlike Western legal systems, taking a life in traditional Igbo society was not punished by capital punishment; instead, severe restitution such as a seven-year exile or a replacement marriage for the deceased was required.', 'Some Specific Rights and Freedoms in Igbo Society', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The two cardinal Igbo maxims expressing the right to life as the most fundamental right are Ndu bu isi and what other phrase?', '["Ndu ka aku", "Igbo enwe eze", "Nwa bu nwa oha", "Ofu aka lutara mmanu"]'::jsonb, 0, 'The right to life in Igbo thought is expressed through two cardinal maxims: Ndu bu isi (life is foremost) and Ndu ka aku (life is greater than wealth).', 'Some Specific Rights and Freedoms in Igbo Society', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Igbo saying ''Igbo enwe eze'' (''the Igbo have no kings'') reflects which characteristic of traditional Igbo political organisation?', '["A famously decentralised and largely participatory, republican political system", "A strict hereditary monarchy", "Rule by a single centralised emperor", "Governance entirely by foreign colonial officers"]'::jsonb, 0, '''Igbo enwe eze'' reflects that the traditional Igbo political system was famously decentralised and republican, with leadership generally consultative rather than authoritarian, and power resting with the people through village assemblies.', 'Some Specific Rights and Freedoms in Igbo Society', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'The Igbo principle ''Nwa bu nwa oha'' (''a child belongs to the community'') emphasises which right?', '["Collective responsibility for children''s upbringing, education, and welfare", "The right of parents to sell their children into servitude", "The exclusion of children from community life", "The right of only the eldest child to inheritance"]'::jsonb, 0, 'The principle ''Nwa bu nwa oha'' emphasises that children are regarded as community responsibilities, with collective upbringing, education, and welfare being a shared duty in Igbo worldview.', 'Rights of Women and Children in Igbo Society', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In traditional Igbo society, who is regarded as the earth goddess and supreme guardian of morality and justice, whose authority underpins environmental protection?', '["Ala", "Amadioha", "Chukwu", "Agwu"]'::jsonb, 0, 'Ala, the earth goddess, is regarded as the supreme guardian of morality, justice, and social order in traditional Igbo society, and violations of customary law (nso ala) were believed to attract sanctions originating from her authority.', 'Traditional Safeguards of Human Rights and Social Justice', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which traditional Igbo institutions functioned as agents of social control and enforced communal decisions, resolving minor disputes?', '["Masquerades and Age Grades", "The colonial court system", "The Nigerian Copyright Commission", "The Organisation of Islamic Nations"]'::jsonb, 0, 'Masquerades and Age Grades functioned as important agents of social control and community governance in traditional Igbo society, enforcing communal decisions and maintaining public order.', 'Traditional Safeguards of Human Rights and Social Justice', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'In difficult disputes where evidence was unclear, which traditional Igbo institution served to establish truth and deter false accusations?', '["Oath-taking and divination institutions", "Written court records", "Colonial magistrate courts", "Trial by foreign arbitration"]'::jsonb, 0, 'Oath-taking before deities and divination served as mechanisms for establishing truth and deterring false accusations, perjury, and injustice in difficult disputes with unclear evidence.', 'Traditional Safeguards of Human Rights and Social Justice', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which of the following is listed among the major human rights violations and forms of social injustice affecting contemporary Nigeria?', '["Police brutality and extrajudicial killings", "Excessive investment in cultural institutions", "Overfunding of art education", "Surplus government spending on museums"]'::jsonb, 0, 'Police brutality and extrajudicial killings are listed among the major human rights violations affecting Nigeria today, alongside issues such as electoral malpractice, corruption, and ethnic discrimination.', 'Human Rights Violations and Social Injustice in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Paulinus Okechukwu Agbo''s essay ''Fractured Coexistence'' primarily examines what subject?', '["Religious conflicts and their impact on national development in Nigeria", "The economics of Nigerian agriculture", "The history of Nigerian independence", "Nigerian constitutional amendments"]'::jsonb, 0, '''Fractured Coexistence: Re-assessing Religious Conflicts and the Fragility of National Development in Nigeria'' examines how religious conflicts have impeded Nigeria''s national development.', 'Introduction to Religious Conflicts in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Mbiti (1990) observed that Africans are what, in relation to religion?', '["Notoriously religious", "Entirely secular", "Indifferent to spiritual matters", "Opposed to all forms of worship"]'::jsonb, 0, 'Mbiti (1990) is quoted as observing that Africans are ''notoriously religious,'' with adherents of Christianity, Islam, and African Traditional Religion often in constant, unhealthy competition.', 'Introduction to Religious Conflicts in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Which two dominant religions are most often associated with violent clashes in Nigeria?', '["Christianity and Islam", "Buddhism and Hinduism", "Judaism and Christianity", "African Traditional Religion and Buddhism"]'::jsonb, 0, 'Christianity and Islam are the two dominant religions whose extremist adherents'' clashes most often come to mind when religious crises in Nigeria are discussed.', 'Introduction to Religious Conflicts in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Nigeria''s membership in which international organisation is interpreted by some as giving Islam greater influence over other religions in the country?', '["The Organisation of Islamic Nations", "The United Nations Security Council", "The African Union", "The World Health Organisation"]'::jsonb, 0, 'Nigeria''s membership in the Organisation of Islamic Nations is interpreted by some as an edge Islam holds over other religions in Nigeria, setting other religions like Christianity into tension with Islam.', 'Religious Crises: Sharia and Islam in Nigeria', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Mandaville and James (2010) define religion as what kind of system?', '["A relatively bounded system of beliefs, symbols, and practices addressing the nature of existence", "A purely political ideology with no spiritual content", "A set of laws enacted by the state", "An economic system for resource distribution"]'::jsonb, 0, 'Mandaville and James (2010) define religion as a relatively bounded system of beliefs, symbols, and practices that addresses the nature of existence, through which communion with others and otherness is lived.', 'Definition of Religion', true, 'second', 2),
  ('gst-212-nigerian-peoples-culture', 'GST212: Nigerian Peoples and Culture', 'University of Nigeria, Nsukka', '', '', '200 Level', 'Scholars of religion largely disagree on what point regarding the definition of religion?', '["There is no general consensus on one universal meaning of the concept", "Religion has never been formally defined by any scholar", "Religion is identical in meaning to culture", "All scholars agree religion means only ''the worship of God''"]'::jsonb, 0, 'There is no general consensus regarding the definition of religion, as no single definition has successfully and adequately captured all aspects of this ''enigma'' called religion.', 'Definition of Religion', true, 'second', 2);
